package br.com.cineo;
import android.app.*;import android.view.*;import android.widget.*;import android.net.Uri;import org.json.*;import java.util.*;import static br.com.cineo.MainActivity.*;
/** Public clips and explicitly labelled launch incentives. No generated social accounts. */
class LaunchHub {
 final MainActivity a;JSONArray clips=new JSONArray();int index=0,nextOffset=0;String scope="";long loadedAt=0;boolean fetching=false;LaunchHub(MainActivity a){this.a=a;}
 void page(String id,String title,String sub){a.page(id,title,sub,3,()->a.profile());}
 void get(String path,MainActivity.Done done){a.call("GET","/v12"+path,null,done);}void post(String path,JSONObject data,MainActivity.Done done){a.call("POST","/v12"+path,data,done);}
 void open(){if(!scope.equals(a.fastCache.scope())||System.currentTimeMillis()-loadedAt>240000){clips=new JSONArray();nextOffset=0;index=0;scope=a.fastCache.scope();}a.page("clips","Clipes","Descubra uma história pelo primeiro episódio.",4,()->a.catalog(false));if(clips.length()>0){show(Math.min(index,clips.length()-1));return;}load(true);}
 void load(boolean play){if(fetching)return;fetching=true;get("/clips?offset="+Math.max(0,nextOffset),r->{fetching=false;JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++)clips.put(rows.getJSONObject(i));nextOffset=r.isNull("next_offset")?-1:r.optInt("next_offset");loadedAt=System.currentTimeMillis();if(play&&clips.length()>index){show(index);return;}if(clips.length()==0){a.empty(a.body,"film","Novas histórias a caminho","Primeiros episódios publicados aparecerão aqui.");if(nextOffset>=0)a.button(a.body,"Buscar mais clipes",RED,()->load(true));a.button(a.body,"Explorar catálogo",CARD,()->a.catalog(false));}else if(play){a.title(a.body,"Você chegou ao fim",24);a.text(a.body,"Explore o catálogo ou volte aos clipes que já viu.",14,MUTED);a.button(a.body,"Voltar aos clipes",RED,()->show(0));}});a.handler.postDelayed(()->fetching=false,20000);}
 void show(int n){JSONObject row=clips.optJSONObject(n);if(row==null)return;index=n;a.safe(()->{JSONObject show=row.getJSONObject("show");show.put("_source","clips");a.play(show,new JSONArray().put(row.getJSONObject("episode")),0,"clips");});}
 boolean active(){return a.drama.active&&"clips".equals(a.activeOrigin);}
 void next(int delta){if(!active()||a.drama.changing)return;int n=index+delta;if(n<0){Toast.makeText(a,"Este é o primeiro clipe.",0).show();return;}if(n<clips.length()){show(n);return;}if(nextOffset>=0){index=n;a.page("clips-next","Mais histórias","Buscando os próximos primeiros episódios.",4,()->open());load(true);}else{Toast.makeText(a,"Você viu todos os clipes disponíveis. Explore as séries completas.",1).show();}}
 void series(){if(!active())return;a.saveProgress();a.pro.syncProgress(true);JSONObject show=a.activeShow;a.details(show,"clips");}
 void follow(LinearLayout parent,JSONObject show){String creator=show.optString("owner_id");if(creator.equals(a.uid)||creator.isEmpty())return;TextView button=a.label("＋ Seguir",10,WHITE);button.setGravity(Gravity.CENTER);button.setMinHeight(a.dp(40));parent.addView(button,new LinearLayout.LayoutParams(-1,a.dp(40)));button.setContentDescription("Seguir o criador");final boolean[] following={false};button.setEnabled(false);a.socialRequest("GET","/v4/follow?kind=creator&target="+creator,null,r->{following[0]=r.optBoolean("following");button.setText(following[0]?"✓ Seguindo":"＋ Seguir");button.setEnabled(true);});button.setOnClickListener(v->{if(!button.isEnabled())return;button.setEnabled(false);a.safe(()->a.socialRequest("POST","/v4/follow",a.obj("kind","creator","target",creator,"following",!following[0]),r->{following[0]=r.optBoolean("following");button.setText(following[0]?"✓ Seguindo":"＋ Seguir");button.setEnabled(true);}));a.handler.postDelayed(()->button.setEnabled(true),15000);});}
 void options(){new AlertDialog.Builder(a).setTitle("Clipes").setItems(new String[]{"Não tenho interesse nesta série","Próximo clipe","Reprodução e economia de internet","Voltar ao início"},(d,n)->{if(n==0){JSONObject show=a.activeShow;a.safe(()->a.socialRequest("POST","/v8/library-choice",a.obj("show_id",show.optInt("id"),"interested",false),r->{int removed=index;JSONArray remaining=new JSONArray();for(int i=0;i<clips.length();i++)if(i!=removed)remaining.put(clips.optJSONObject(i));clips=remaining;if(clips.length()>0)show(Math.min(index,clips.length()-1));else{loadedAt=0;open();}}));}if(n==1)next(1);if(n==2)a.playerExtras.settings();if(n==3)a.catalog(false);}).show();}
 void missions(){page("missions","Missões do Criador","Seu trabalho pode render bônus de lançamento.");get("/missions",r->{JSONObject program=r.getJSONObject("program");metric("BÔNUS CREDITADOS",a.studioPro.money(r.optLong("reward_cents")));a.gap(a.body,12);a.title(a.body,"Primeira série · "+a.studioPro.money(program.optInt("first_cents")),22);a.text(a.body,"Uma vez por criador, após a primeira série participante ser aprovada e entrar no ar com um episódio validado.",14,MUTED);a.title(a.body,"Cada episódio · "+a.studioPro.money(program.optInt("episode_cents")),21);a.text(a.body,"O valor fica pendente durante a análise e é creditado após aprovação, validação técnica e publicação. Os valores de cada série são os registrados ao entrar na missão.",14,MUTED);a.text(a.body,r.optString("note"),12,MUTED);if(!r.optBoolean("joined")){CheckBox accept=new CheckBox(a);accept.setText("Li as regras. Quero participar antes de publicar minha série.");accept.setTextColor(WHITE);a.body.addView(accept);if(program.optBoolean("enabled"))a.button(a.body,"Participar das missões",RED,()->{if(!accept.isChecked()){a.notice("Leia e aceite as regras para participar.",true);return;}a.safe(()->post("/missions",a.obj("accept",true),x->missions()));});else a.text(a.body,"Novas participações estão pausadas.",14,AMBER);}else{if(!r.optBoolean("first_eligible"))a.text(a.body,"Você já tinha uma série aprovada ao entrar. O bônus de primeira série não se aplica; seus episódios participantes continuam elegíveis.",13,MUTED);JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.button(a.body,"Criar minha primeira produção",RED,()->a.creatorHub.home());for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i),s=e.optJSONObject("show");a.gap(a.body,14);a.title(a.body,s==null?"Produção":s.optString("title"),20);a.text(a.body,e.optInt("episodes")+" episódios · "+e.optInt("paid_episodes")+" creditados",14,MUTED);a.text(a.body,"Creditado: "+a.studioPro.money(e.optLong("released_cents"))+"\nEpisódios pendentes: "+a.studioPro.money(e.optLong("pending_episode_cents")),14,WHITE);if(e.optBoolean("first_possible"))a.text(a.body,"Pode liberar "+a.studioPro.money(e.optLong("pending_first_cents"))+" pela primeira série. Esse bônus é único, mesmo com várias séries participantes.",12,MUTED);}}a.gap(a.body,18);a.title(a.body,"Histórico dos bônus",22);JSONArray ledger=r.getJSONArray("ledger");if(ledger.length()==0)a.text(a.body,"Os créditos aparecerão aqui após a publicação válida.",14,MUTED);for(int i=0;i<ledger.length();i++){JSONObject l=ledger.getJSONObject(i);a.title(a.body,a.studioPro.money(l.optLong("amount_cents")),18);a.text(a.body,l.optString("reason")+" · "+a.pro.date(l.optString("created_at")),13,MUTED);}a.button(a.body,"Ver saldo e saques",CARD,()->{a.studioPro.owner="";a.studioPro.finance();});});}
 void admin(){page("launch-admin","Lançamento e descoberta","Público real, incentivos identificados e histórico.");a.menu("search","Buscar perfis e séries","Verificados, clipes e bônus por criador",()->search());a.menu("check","Programa de missões","Valores, pausa e orçamento",()->program());a.menu("chart","Audiência e integridade","Reproduções e sinais para revisão",()->health());a.menu("film","Curadoria dos clipes","Prioridades e séries participantes",()->curation());a.menu("history","Histórico administrativo","Motivos e alterações registradas",()->history());a.menu("gear","Simulador de testes","Prévia local sem ganhos nem público fictício",()->simulator());}
 void search(){page("launch-search","Buscar perfis e séries","Pesquise pelo nome, título ou código completo.");EditText query=a.field(a.body,"PESQUISA","Digite pelo menos dois caracteres",false);LinearLayout results=a.col();a.button(a.body,"Pesquisar",RED,()->get("/admin/search?q="+Uri.encode(query.getText().toString().trim()),r->{results.removeAllViews();JSONArray people=r.getJSONArray("profiles"),shows=r.getJSONArray("shows");a.title(results,"Perfis · "+people.length(),20);for(int i=0;i<people.length();i++){JSONObject p=people.getJSONObject(i);a.button(results,p.optString("name")+(p.optBoolean("verified")?" ✓":""),CARD,()->profile(p));}a.title(results,"Séries · "+shows.length(),20);for(int i=0;i<shows.length();i++){JSONObject s=shows.getJSONObject(i);a.button(results,s.optString("title")+" · "+s.optString("status"),CARD,()->clipForm(s));}}));a.body.addView(results);}
 void profile(JSONObject p){page("launch-profile",p.optString("name"),p.optString("user_id"));a.text(a.body,"O selo indica identidade confirmada pela administração. Destaque editorial é uma escolha de curadoria e não equivale à verificação.",14,MUTED);a.button(a.body,"Abrir perfil público",CARD,()->a.pro.creator(p.optString("user_id")));a.button(a.body,p.optBoolean("verified")?"Retirar verificação":"Verificar identidade",RED,()->verify(p.optString("user_id"),p.optBoolean("verified")));a.button(a.body,"Conceder bônus identificado",CARD,()->bonus(p));a.button(a.body,"Resultados deste criador",CARD,()->{a.studioPro.owner=p.optString("user_id");a.studioPro.home();});}
 void verify(String id,boolean verified){page("launch-verify","Verificação do perfil","Registre a conferência da identidade.");EditText reason=a.field(a.body,"MOTIVO","Informe a conferência realizada",false);a.button(a.body,verified?"Confirmar retirada do selo":"Confirmar verificação",RED,()->a.safe(()->post("/admin/verify",a.obj("user_id",id,"verified",!verified,"reason",reason.getText().toString()),r->admin())));}
 void bonus(JSONObject p){page("launch-bonus","Bônus de lançamento",p.optString("name"));final String request=UUID.randomUUID().toString();EditText amount=a.field(a.body,"VALOR EM REAIS","Ex.: 5,00",false),reason=a.field(a.body,"MOTIVO E CONDIÇÕES CUMPRIDAS","Ex.: incentivo de lançamento pela publicação",false);amount.setInputType(8194);reason.setSingleLine(false);reason.setMinLines(3);a.text(a.body,"Este crédito é financiado por você e ficará disponível no saldo, identificado como bônus. Não cria views ou seguidores. Pagamento e saque seguem as regras vigentes.",14,MUTED);a.button(a.body,"Conferir bônus",RED,()->a.safe(()->{long cents=a.studioPro.cents(amount);if(cents<=0){a.notice("Informe um valor positivo.",true);return;}a.studioPro.confirm("Creditar "+a.studioPro.money(cents)+" como bônus para "+p.optString("name")+"?",()->post("/admin/bonus",a.obj("creator_id",p.optString("user_id"),"request_id",request,"amount_cents",cents,"reason",reason.getText().toString()),r->admin()));}));}
 void program(){page("mission-program","Regras das missões","Alterações de valores valem para novas séries participantes.");get("/admin/program",r->{EditText first=a.field(a.body,"PRIMEIRA SÉRIE · REAIS","1,50",false),episode=a.field(a.body,"POR EPISÓDIO · REAIS","0,01",false),budget=a.field(a.body,"ORÇAMENTO TOTAL · OPCIONAL","Vazio significa sem teto definido",false),reason=a.field(a.body,"MOTIVO","Registre a alteração",false);for(EditText e:new EditText[]{first,episode,budget})e.setInputType(8194);first.setText(a.studioPro.decimal(r.optLong("first_cents")));episode.setText(a.studioPro.decimal(r.optLong("episode_cents")));if(!r.isNull("budget_cents"))budget.setText(a.studioPro.decimal(r.optLong("budget_cents")));CheckBox enabled=new CheckBox(a);enabled.setText("Aceitar novos participantes e novas séries");enabled.setTextColor(WHITE);enabled.setChecked(r.optBoolean("enabled"));a.body.addView(enabled);a.text(a.body,"Missões creditadas: "+a.studioPro.money(r.optLong("spent_cents"))+"\nBônus manuais: "+a.studioPro.money(r.optLong("bonus_cents")),15,WHITE);a.text(a.body,"Pausar não apaga participações existentes. O teto limita novos créditos de missões, incluindo séries já inscritas; pendências podem ser liberadas quando houver orçamento. Bônus manuais são separados do teto. Não há depósito ou pagamento automático.",13,MUTED);a.button(a.body,"Conferir regras",RED,()->a.safe(()->{JSONObject payload=a.obj("enabled",enabled.isChecked(),"first_cents",a.studioPro.cents(first),"episode_cents",a.studioPro.cents(episode),"budget_cents",budget.getText().toString().trim().isEmpty()?JSONObject.NULL:a.studioPro.cents(budget),"revision",r.optInt("revision"),"reason",reason.getText().toString());a.studioPro.confirm("Salvar estas regras e o orçamento das missões?",()->post("/admin/program",payload,x->program()));}));});}
 void clipForm(JSONObject s){page("clip-curation",s.optString("title"),"O primeiro episódio precisa estar aprovado e publicado.");get("/admin/clips",r->{JSONObject found=new JSONObject();JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).optInt("show_id")==s.optInt("id"))found=rows.getJSONObject(i);CheckBox enabled=new CheckBox(a);enabled.setText("Participar dos Clipes");enabled.setChecked(found.optBoolean("enabled",true));enabled.setTextColor(WHITE);a.body.addView(enabled);EditText position=a.field(a.body,"PRIORIDADE · MENOR APARECE ANTES","100",false),reason=a.field(a.body,"MOTIVO EDITORIAL","Justifique sua escolha",false);position.setInputType(2);position.setText(String.valueOf(found.optInt("position",100)));a.button(a.body,"Salvar curadoria",RED,()->a.safe(()->post("/admin/clips",a.obj("show_id",s.optInt("id"),"enabled",enabled.isChecked(),"position",Integer.parseInt(position.getText().toString()),"reason",reason.getText().toString()),x->curation())));a.button(a.body,"Abrir série",CARD,()->a.loadDetail(s.optInt("id"),"admin"));});}
 void curation(){page("clip-curation-list","Curadoria dos Clipes","Somente conteúdo público válido entra no feed.");a.button(a.body,"Encontrar uma série",RED,()->search());get("/admin/clips",r->{JSONArray rows=r.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject x=rows.getJSONObject(i);a.text(a.body,"Série "+x.optInt("show_id")+" · "+(x.optBoolean("enabled")?"Habilitada":"Oculta")+" · prioridade "+x.optInt("position")+"\n"+x.optString("reason"),14,MUTED);}});}
 void health(){page("launch-health","Audiência e integridade","Observação dos últimos sete dias.");get("/admin/health",r->{metric("SESSÕES DE REPRODUÇÃO",a.studioPro.number(r.optLong("sessions")));metric("VIEWS ELEGÍVEIS",a.studioPro.number(r.optLong("qualified_views")));metric("SESSÕES NOS CLIPES",a.studioPro.number(r.optLong("clip_sessions")));metric("VIEWS DOS CLIPES",a.studioPro.number(r.optLong("clip_views")));a.text(a.body,"Contas com mais de 100 sessões no último dia: "+r.optInt("high_repeat_accounts")+". É um sinal para revisão, não prova de fraude.",14,MUTED);a.text(a.body,"Reproduções próprias, repetidas além do limite diário ou sem tempo válido não geram novas views remuneradas. Bônus de missões ficam separados.",13,MUTED);});}
 void history(){page("launch-history","Histórico administrativo","Alterações registradas com motivo.");get("/admin/history",r->{JSONArray rows=r.getJSONArray("items");if(rows.length()==0)a.text(a.body,"Ainda não houve alterações neste módulo.",14,MUTED);for(int i=0;i<rows.length();i++){JSONObject h=rows.getJSONObject(i),d=h.optJSONObject("detail");a.title(a.body,h.optString("action").replace("launch_program","Regras das missões").replace("launch_verify","Selo de verificação").replace("launch_clip","Curadoria dos clipes"),18);a.text(a.body,h.optString("target")+" · "+a.pro.date(h.optString("created_at"))+"\n"+(d==null?"":d.optString("reason")),13,MUTED);}});}
 void simulator(){page("launch-simulator","Simulador de testes","DADOS SIMULADOS · SEM CRÉDITO FINANCEIRO");EditText count=a.field(a.body,"QUANTIDADE DE TESTE","Ex.: 1000",false);count.setInputType(2);LinearLayout result=a.col();a.button(a.body,"Visualizar cenário local",CARD,()->a.safe(()->{long n=Long.parseLong(count.getText().toString());if(n<0||n>1000000)throw new Exception("Use de zero a um milhão.");result.removeAllViews();a.title(result,n+" reproduções simuladas",22);a.text(result,"Cenário: "+a.studioPro.money(n*40.0/1000)+" teóricos. Não foram criados perfis, interações, views públicas ou saldo para saque.",14,MUTED);}));a.body.addView(result);}
 void metric(String label,String value){LinearLayout row=a.row();a.body.addView(row);a.studioPro.card(row,label,value);a.gap(a.body,10);}
 void reset(){clips=new JSONArray();scope="";index=0;nextOffset=0;fetching=false;loadedAt=0;}
}
